      // 追加一对监听器却从不移除，每重建一代净增两个闭包（持有已废弃的 grace 定时器
      // 与被移出 DOM 的触发元素）。这里改为两处固定监听器 + 一个「当前面板的关闭钩子」
      // 指针（tipActiveHide），由面板在 mouseenter 时登记，真正关闭后解除。
      var tipActiveHide = null
      function sharedTipMouseEnter() {
